/* B"H — Automation graph: shader-node cockpit skin */
.automation-panel-content {
  min-height: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
}
.automation-panel-content .right-panel-body {
  min-height: 0;
  overflow: auto;
}
.automation-graph-panel {
  --node-blue: rgba(34,211,238,.95);
  --node-purple: rgba(168,85,247,.95);
  --node-green: rgba(52,211,153,.95);
  --node-red: rgba(248,113,113,.95);
}
.automation-graph-panel .panel-note {
  border: 1px solid rgba(34,211,238,.16);
  border-radius: 18px;
  padding: .72rem .85rem;
  background: linear-gradient(135deg, rgba(8,47,73,.32), rgba(30,41,59,.24));
  color: rgba(226,232,240,.84);
}
.graph-canvas {
  min-height: 260px;
  overflow: auto;
  counter-reset: graph-node;
}
.graph-canvas::before {
  content: "Automation Node Field";
  position: sticky;
  top: .4rem;
  z-index: 2;
  width: fit-content;
  padding: .24rem .62rem;
  border: 1px solid rgba(34,211,238,.24);
  border-radius: 999px;
  background: rgba(2,6,23,.78);
  color: rgba(186,230,253,.88);
  font-size: .72rem;
  letter-spacing: .08em;
  text-transform: uppercase;
  backdrop-filter: blur(8px);
}
.graph-node {
  counter-increment: graph-node;
  isolation: isolate;
  overflow: hidden;
}
.graph-node::after {
  content: counter(graph-node, decimal-leading-zero);
  position: absolute;
  right: .7rem;
  top: .55rem;
  color: rgba(125,211,252,.20);
  font-size: 1.5rem;
  font-weight: 950;
  letter-spacing: -.08em;
  pointer-events: none;
}
.graph-node-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: .5rem;
  margin: -.15rem -.15rem .35rem;
  padding: .55rem .6rem;
  border-radius: .85rem;
  background: linear-gradient(90deg, rgba(15,23,42,.82), rgba(8,47,73,.34));
  border: 1px solid rgba(125,211,252,.12);
}
.graph-node-head button {
  border: 1px solid rgba(248,113,113,.26);
  border-radius: 999px;
  background: rgba(127,29,29,.18);
  color: #fecaca;
  width: 2rem;
  height: 2rem;
}
.graph-node-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(165px, 1fr));
  gap: .55rem;
}
.graph-node .automation-field,
.graph-node label:not(.automation-field) {
  display: grid;
  gap: .25rem;
  min-width: 0;
  color: rgba(226,232,240,.75);
  font-size: .74rem;
}
.graph-node input,
.graph-node select,
.graph-node textarea {
  min-width: 0;
  border: 1px solid rgba(125,211,252,.20);
  border-radius: .75rem;
  background: rgba(2,6,23,.68);
  color: #f8fdff;
  padding: .5rem .58rem;
}
.graph-node-prompt textarea {
  min-height: 5.5rem !important;
}
.graph-node-condition { box-shadow: 0 16px 40px rgba(250,204,21,.06), inset 0 1px 0 rgba(255,255,255,.05); }
.graph-node-send { box-shadow: 0 16px 40px rgba(34,211,238,.08), inset 0 1px 0 rgba(255,255,255,.05); }
.graph-node-archive { box-shadow: 0 16px 40px rgba(52,211,153,.07), inset 0 1px 0 rgba(255,255,255,.05); }
.graph-node-delay { border-color: rgba(192,132,252,.34); }
.graph-node-delay::before { background: linear-gradient(180deg, #c084fc, #22d3ee); box-shadow: 0 0 18px rgba(192,132,252,.34); }
.graph-node-jump { border-color: rgba(96,165,250,.34); }
.graph-node-jump::before { background: linear-gradient(180deg, #60a5fa, #34d399); box-shadow: 0 0 18px rgba(96,165,250,.34); }
.graph-node .graph-toggle {
  display: flex !important;
  align-items: center;
  gap: .55rem;
}
.graph-start-field {
  border-color: rgba(34,211,238,.34) !important;
  box-shadow: 0 0 28px rgba(34,211,238,.08), inset 0 1px 0 rgba(255,255,255,.06) !important;
}
.graph-json-field textarea {
  background:
    linear-gradient(90deg, rgba(34,211,238,.05), transparent),
    rgba(2,6,23,.82) !important;
  color: #dffbff !important;
  text-shadow: 0 0 12px rgba(34,211,238,.08);
}
